public class LibraryNightlyAudit { static class LibraryMember{static int count=100;final String memberNumber="LIB-"+(++count);int books;LibraryMember(int l){}void borrowBook(){books++;}void borrowBook(String genre){borrowBook();}static boolean isValidRenewalCode(String c){return c!=null&&c.length()==4&&c.charAt(0)=='R'&&Character.isDigit(c.charAt(1))&&Character.isDigit(c.charAt(2))&&Character.isUpperCase(c.charAt(3));}}static class FacultyMember extends LibraryMember{FacultyMember(int l,String d){super(l);}}static String processNightlyAudit(LibraryMember[] x){int ok=0,nil=0,f=0;for(LibraryMember m:x){if(m==null){nil++;continue;}ok++;if(m instanceof FacultyMember)f++;}return ok+" processed | "+nil+" null skipped | "+f+" faculty | "+(ok-f)+" regular";}public static void main(String[]a){System.out.println(processNightlyAudit(new LibraryMember[]{new FacultyMember(5,"Physics"),null,new LibraryMember(3)}));} }
